    if isinstance(exp, dict) and 'llama' in eid.lower():
        res = exp.get('results', {})
        if res:
            ign = res.get('ign_f1', res.get('Ign_F1', res.get('ign-f1', 'N/A')))
            if ign != 'N/A' and ign is not None:
                print(f'{eid}: ign_f1={ign}, results_keys={list(res.keys())[:5]}')

# Search for 8b
print()
print('=== All 8B entries with results ===')
for eid, exp in exps.items():
    if isinstance(exp, dict) and '8b' in eid.lower():
        res = exp.get('results', {})
        if res:
            # check all keys for ign_f1
            for k, v in res.items():
                if 'ign' in k.lower() or 'f1' in k.lower():
                    print(f'{eid}: {k}={v}')
